-- Built off Chapter Scorecard by Rossi
-- https://steamcommunity.com/sharedfiles/filedetails/?id=2535178173&searchtext=scorecard

function onSave()
    local state = {
        stonks = {
            pictures = self.UI.getAttribute("motion_pictures", "text"),
            steamships = self.UI.getAttribute("allied_steamships", "text"),
            utilities = self.UI.getAttribute("national_utilities", "text"),
            radio = self.UI.getAttribute("general_radio", "text"),
            railways = self.UI.getAttribute("united_railways", "text"),
            motors = self.UI.getAttribute("american_motors", "text"),
        }
    }
    return JSON.encode(state)
end

function onLoad(script_state)

	local state = JSON.decode(script_state)

  function buildButtons()
    local buttons = buildButtonParams()
    for func, pos in pairs(buttons) do
      self.createButton(buttonParams(func, pos))
    end
  end

  function buttonParams(func, pos)
    local buttonParams = {
      click_function = func,
      function_owner = self,
      label = '',
      position = pos,
      width = 80,
      height = 80
    }
    return buttonParams
  end

  buildButtons()

  self.UI.setAttribute("motion_pictures", "text", state.stonks.pictures)
  self.UI.setAttribute("allied_steamships", "text", state.stonks.steamships)
  self.UI.setAttribute("national_utilities", "text", state.stonks.utilities)
  self.UI.setAttribute("general_radio", "text", state.stonks.radio)
  self.UI.setAttribute("united_railways", "text", state.stonks.railways)
  self.UI.setAttribute("american_motors", "text", state.stonks.motors)

  Wait.frames(function() calculateDividends() end, 10)

end

function buildButtonParams()
  local buttons = {}
  --Motion Pictures
  buttons['incPictures'] = {.62, .01, -.81}
  buttons['decPictures'] = {.35, .01, -.81}
  
  --Allied Steamships
  buttons['incSteamships'] = {.62, .01, -.61}
  buttons['decSteamships'] = {.35, .01, -.61}
  
  --National Utilities
  buttons['incUtilities'] = {.62, .01, -.41}
  buttons['decUtilities'] = {.35, .01, -.41}
  
  --General Radio
  buttons['incRadio'] = {.62, .01, -.21}
  buttons['decRadio'] = {.35, .01, -.21}
  
  --United Railways
  buttons['incRailways'] = {.62, .01, -.01}
  buttons['decRailways'] = {.35, .01, -.01}
  
  --American Motors
  buttons['incMotors'] = {.62, .01, .19}
  buttons['decMotors'] = {.35, .01, .19}
  return buttons
end



function incPictures()
  Wait.frames(function() gainStock("motion_pictures") end, 1)
end

function decPictures()
    Wait.frames(function() loseStock("motion_pictures") end, 1)
end

function incSteamships()
  Wait.frames(function() gainStock("allied_steamships") end, 1)
end

function decSteamships()
  Wait.frames(function() loseStock("allied_steamships") end, 1)
end

function incUtilities()
  Wait.frames(function() gainStock("national_utilities") end, 1)
end

function decUtilities()
  Wait.frames(function() loseStock("national_utilities") end, 1)
end

function incRadio()
  Wait.frames(function() gainStock("general_radio") end, 1)
end

function decRadio()
  Wait.frames(function() loseStock("general_radio") end, 1)
end

function incRailways()
  Wait.frames(function() gainStock("united_railways") end, 1)
end

function decRailways()
  Wait.frames(function() loseStock("united_railways") end, 1)
end

function incMotors()
  Wait.frames(function() gainStock("american_motors") end, 1)
end

function decMotors()
  Wait.frames(function() loseStock("american_motors") end, 1)
end

function gainStock(stock)
  local security = self.UI.getAttribute(stock, "text")
  security = tonumber(security)
  self.UI.setAttribute(stock, "text", math.min(security + 1, 5))
  Wait.frames(function() calculateDividends() end, 1)
end

function loseStock(stock)
  local security = self.UI.getAttribute(stock, "text")
  security = tonumber(security)
  self.UI.setAttribute(stock, "text", math.max(security - 1, 0))
  Wait.frames(function() calculateDividends() end, 1)
end

function calculateDividends()
  local motionpictures = self.UI.getAttribute("motion_pictures", "text")
  local alliedsteamships = self.UI.getAttribute("allied_steamships", "text")
  local nationalutilities = self.UI.getAttribute("national_utilities", "text")
  local generalradio = self.UI.getAttribute("general_radio", "text")
  local unitedrailways = self.UI.getAttribute("united_railways", "text")
  local americanmotors = self.UI.getAttribute("american_motors", "text")
  local dividends = (10*(motionpictures^2)) + (11*(alliedsteamships^2)) + (12*(nationalutilities^2)) + (13*(generalradio^2)) + (14*(unitedrailways^2)) + (15*(americanmotors^2))
  self.UI.setAttribute("dividends", "text", dividends)
  local half_dividends = math.ceil(0.5*((10*(motionpictures^2)) + (11*(alliedsteamships^2)) + (12*(nationalutilities^2)) + (13*(generalradio^2)) + (14*(unitedrailways^2)) + (15*(americanmotors^2))))
  self.UI.setAttribute("half_dividends", "text", half_dividends)
